from pathlib import Path
from html import escape
P=Path(__file__).parent
# x,y,width,depth in meters, north = +Y; these are spatial footprints, not graph nodes.
spaces=[('T · service arrival',38,2,24,14,'#bd8257'),('West ticket hall',16,8,22,18,'#baae88'),('East ticket hall',62,8,22,18,'#9cae9c'),('Yellow interchange',8,22,22,12,'#d1b956'),('Red approach',8,34,20,14,'#bca2a0'),('A · RED PLATFORM',4,48,28,24,'#c67c73'),('A transfer',28,52,12,10,'#c6ad9c'),('Lower transfer hall · z0',36,38,28,26,'#b9b7a7'),('T mid',44,16,12,22,'#d1c49c'),('Blue approach',72,26,20,22,'#9fbdc9'),('B · BLUE SCISSOR',68,48,28,24,'#75a9c2'),('B transfer',60,52,12,10,'#a6bcc1'),('Relay',42,64,16,16,'#aeaca1'),('A rear',14,72,10,10,'#c6ad9c'),('B rear',78,72,10,10,'#a6bcc1'),('CT rear concourse',14,80,74,6,'#9eabb0'),('CT · emergency stair',38,84,24,10,'#7fabc0')]
obstacles=[('T-screen',44,19,7,2,7),('West-switch',8,38,12,2,5),('East-switch',80,36,12,2,5),('Relay-screen',46,68,8,2,7),('Core',44,54,8,5,8),('CT-screen',43,84,14,2,7),('Red-car-01',8,52,4,12,3.2),('Red-car-02',14,62,4,9,3.5),('Blue-car-01',77,59,16,3.6,3.2),('Blue-car-02',82,50,4,9,3.5),('A-cabinet',25,62,3,4,2.6),('B-cabinet',70,65,4,3,2.6)]
def svg(stage):
 s=['<svg xmlns="http://www.w3.org/2000/svg" width="1440" height="1040" viewBox="0 0 1440 1040">','<rect width="1440" height="1040" fill="#101e29"/>','<style>text{font-family:Arial,sans-serif;fill:#ecede6}.room{font-size:10px;font-weight:700;paint-order:stroke;stroke:#172934;stroke-width:2.5}.small{font-size:13px}.note{font-size:16px;fill:#c0cdd0}</style>',f'<text x="40" y="42" font-size="28" font-weight="700">AFTERSHOCK / 5v5 DEFUSAL / {stage}</text>','<text x="40" y="70" class="note">Earthquake-shattered subway interchange · 100 × 96 m · meters, Z-up · N ↑ · origin southwest</text>']
 def rect(x,y,w,d,fill,stroke='#223642',sw=1): return f'<rect x="{40+x*8.6}" y="{920-(y+d)*8.6}" width="{w*8.6}" height="{d*8.6}" fill="{fill}" stroke="{stroke}" stroke-width="{sw}"/>'
 def label(x,y,t,size=10): return f'<text x="{40+x*8.6}" y="{920-y*8.6}" class="room" font-size="{size}">{escape(t)}</text>'
 for n,x,y,w,d,c in spaces:s+=[rect(x,y,w,d,c),label(x+0.7,y+d/2,n)]
 # Upper bridge has one southern access and two north-facing descents. Lower transfer crosses beneath it.
 s += [rect(34,38,32,10,'#cba565','#ffeac5',2),label(35,45,'MEZZANINE +4 / over lower transfer'),rect(38,26,4,12,'#d8c093'),rect(34,48,4,12,'#d8c093'),rect(62,48,4,12,'#d8c093')]
 for x,y,direction in [(38,26,'↑ +4'),(34,48,'↓ 0'),(62,48,'↓ 0')]:
  for k in range(12):s.append(rect(x,y+k,4,.08,'#4b5a5c'))
  s.append(label(x+.1,y+6,direction))
 for n,x,y,w,d,h in obstacles:s += [rect(x,y,w,d,'#465358'),label(x+.3,y+d/2,n)]
 s += [rect(46,40,4,4,'#465358'),label(46,42,'kiosk'),rect(20,55,6,5,'none','#ffd572',3),label(21,58,'A'),rect(70,54,6,5,'none','#ffd572',3),label(71,57,'B')]
 for x,y in [(43,7),(46,7),(49,7),(52,7),(55,7),(43,90),(46,90),(49,90),(52,90),(55,90)]:s.append(f'<circle cx="{40+x*8.6}" cy="{920-y*8.6}" r="3.5" fill="#fff5ce"/>')
 s += ['<text x="950" y="130" font-size="22" font-weight="700">A STATION IN THREE JOURNEYS</text>','<text x="950" y="165" class="note">West: tickets → yellow switchback</text>','<text x="950" y="190" class="note">→ derailed Red Line / site A.</text>','<text x="950" y="235" class="note">East: shuttered kiosks → blue throat</text>','<text x="950" y="260" class="note">→ scissor collision / site B.</text>','<text x="950" y="305" class="note">Middle: stairs → broken ticket bridge</text>','<text x="950" y="330" class="note">over lower transfer → either wing.</text>','<text x="950" y="385" font-size="22" font-weight="700">READING THE DRAWING</text>','<text x="950" y="420" class="note">Gold = upper floor, z +4m.</text>','<text x="950" y="445" class="note">Steps = reversible vertical transfer.</text>','<text x="950" y="470" class="note">Gray = tall fixed occluder / train.</text>','<text x="950" y="495" class="note">Gold boxes = provisional plant zones.</text>','<text x="950" y="520" class="note">All other floors are z 0m.</text>','<text x="950" y="565" class="note">Rough spatial proposal; not a balance claim.</text>','<text x="950" y="590" class="note">Static crash tableau; no live train damage.</text>','<text x="950" y="635" class="note">5 T south / 5 CT north.</text>','<text x="950" y="660" class="note">Single bomb, A or B, no round respawn.</text>','<text x="950" y="705" class="note">Upper route joins site-side receiving halls;</text>','<text x="950" y="730" class="note">it does not open directly behind defenders.</text>','</svg>']
 return ''.join(s)
(P/'layout-r01.svg').write_text(svg('SPATIAL SKETCH r01'))
